mapper.select:
SELECT * FROM consult
WHERE gym_id = #{gymId}
AND type=#{type}
ORDER BY consult_date DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM consult
WHERE gym_id = #{gymId}
AND type=#{type}

mapper.update:
UPDATE consult
SET type=#{consult.type}, name=#{consult.name}, phone=#{consult.phone}, gender=#{consult.gender},
    interest=#{consult.interest}, content=#{consult.content}, result=#{consult.result},
    consult_date=#{consult.consultDate}, staff_name=#{consult.staffName}
WHERE id=#{consult.id} AND gym_id=#{gymId}

mapper.select:
SELECT SUM(CASE WHEN type='NEW' THEN 1 ELSE 0 END) AS newConsult, SUM(CASE WHEN type='EXISTING' THEN 1 ELSE 0 END) AS existingConsult FROM consult WHERE gym_id = #{gymId}
AND consult_date BETWEEN DATE_SUB(#{date}, INTERVAL WEEKDAY(#{date}) DAY) AND DATE_ADD(DATE_SUB(#{date}, INTERVAL WEEKDAY(#{date}) DAY), INTERVAL 6 DAY)
AND DATE_FORMAT(consult_date, '%Y-%m') = DATE_FORMAT(#{date}, '%Y-%m')
AND consult_date=#{date}
